          (_occHas(vx, vy + 1, vz) ? 1 : 0) + (_occHas(vx, vy - 1, vz) ? 1 : 0) +
          (_occHas(vx, vy, vz + 1) ? 1 : 0) + (_occHas(vx, vy, vz - 1) ? 1 : 0);
