        for (const [k, f] of _floorOf) { const c = k.indexOf(","); _bed.push(+k.slice(0, c), f, +k.slice(c + 1)); }
        if (_bed.length) { const d = _di32(layers.dirt); const merged = new Int32Array(d.length + _bed.length); merged.set(d, 0); merged.set(_bed, d.length); layers.dirt = merged; }
