        const bx0 = minX - 1, bx1 = maxX + 1, bz0 = minZ - 1, bz1 = maxZ + 1;
        const outside = new Set<string>();
        const stack: Array<[number, number]> = [];
        const pushIf = (x: number, z: number) => {
          if (x < bx0 || x > bx1 || z < bz0 || z > bz1) return;
          const k = x + "," + z;
          if (outside.has(k) || surfTop.has(k)) return;
          outside.add(k); stack.push([x, z]);
        };
        for (let x = bx0; x <= bx1; x++) { pushIf(x, bz0); pushIf(x, bz1); }
        for (let z = bz0; z <= bz1; z++) { pushIf(bx0, z); pushIf(bx1, z); }
        while (stack.length) { const [x, z] = stack.pop()!; for (const [dx, dz] of DIRS) pushIf(x + dx, z + dz); }

        let holes: string[] = [];
        for (let x = minX; x <= maxX; x++) for (let z = minZ; z <= maxZ; z++) {
          const k = x + "," + z;
          if (!surfTop.has(k) && !outside.has(k)) holes.push(k);
        }
        const holeKeys = holes.slice();
