        const seed = Math.abs(w.id.split("").reduce((h, c) => Math.imul(h ^ c.charCodeAt(0), 16777619), 2166136261));
        const anchor = chooseConstructionSite(w, 13, 13);
        if (!anchor) return { ok: false, reason: "no valid settlement anchor" };
        const plan = createSettlementPlan(lv, anchor, seed ^ builtStructuresRef.current.length, performance.now());
        plan.stage = "buildings"; plan.status = "active";
        (w as any).settlementPlan = plan;
        (w as any).constructionProject = null;
        w.plan = null;
