      (window as any).__tw.setWorldNormalBias = (v: number) => {
        sun.shadow.normalBias = v; sun.shadow.needsUpdate = true;
        return { worldNormalBias: v };
      };
      (window as any).__tw.setWorldBias = (v: number) => {
        sun.shadow.bias = v; sun.shadow.needsUpdate = true;
        return { worldBias: v };
      };
      // WORLD map size (the wide/terrain light). Bigger = crisper tree shadows,
      // more VRAM. Pair with setWorldHalf to trade coverage for density.
