      (window as any).__tw.setShadowRadius = (v: number) => {
        sun.shadow.radius = v; sun.shadow.needsUpdate = true;
        return { worldShadowRadius: v };
      };
      (window as any).__tw.setHeroShadowRadius = (v: number) => {
        sunNear.shadow.radius = v; sunNear.shadow.needsUpdate = true;
        return { heroShadowRadius: v };
      };
